insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000491011', '40000000-0000-4000-8000-000000049101', 'Comece identificando qual relação vetorial ou geométrica está sendo pedida; essa escolha vem antes da substituição numérica.', 1), ('60000000-0000-4000-8000-000000491012', '40000000-0000-4000-8000-000000049101', 'Multiplique componentes correspondentes.', 2), ('60000000-0000-4000-8000-000000491013', '40000000-0000-4000-8000-000000049101', 'Some os três produtos, preservando o sinal negativo.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049101', '$u \cdot v=2$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. O produto escalar combina componentes correspondentes e produz um número real. Ele conecta a álgebra à geometria por meio de ortogonalidade, ângulos, projeções e trabalho; por isso conferimos também o significado do resultado. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000491011', '40000000-0000-4000-8000-000000049101', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000491012', '40000000-0000-4000-8000-000000049101', 'Multiplique', '$1 \cdot2+1 \cdot1+(-1) \cdot1.$', 2), ('70000000-0000-4000-8000-000000491013', '40000000-0000-4000-8000-000000049101', 'Some', '$2+1-1.$', 3), ('70000000-0000-4000-8000-000000491014', '40000000-0000-4000-8000-000000049101', 'Conclua', '$u \cdot v=2.$', 4), ('70000000-0000-4000-8000-000000491015', '40000000-0000-4000-8000-000000049101', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
