insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049117', '$k=-7$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. O produto escalar combina componentes correspondentes e produz um número real. Ele conecta a álgebra à geometria por meio de ortogonalidade, ângulos, projeções e trabalho; por isso conferimos também o significado do resultado. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
