insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000491481', '40000000-0000-4000-8000-000000049148', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000491482', '40000000-0000-4000-8000-000000049148', 'Calcule na ordem direta', '$u \times v=(0,0,99).$', 2), ('70000000-0000-4000-8000-000000491483', '40000000-0000-4000-8000-000000049148', 'Inverta a ordem', '$v \times u=-(u \times v).$', 3), ('70000000-0000-4000-8000-000000491484', '40000000-0000-4000-8000-000000049148', 'Conclua', '$v \times u=(0,0,-99).$', 4), ('70000000-0000-4000-8000-000000491485', '40000000-0000-4000-8000-000000049148', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
